using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Windows.Forms;using System.Threading.Tasks;

internal static class Updater {
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();if(args.Length!=1)return;var form=new Form{Text="星匣 · 更新",Width=460,Height=180,StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false};var label=new Label{Dock=DockStyle.Fill,Padding=new Padding(25),Text="正在等待星匣保存并关闭…",Font=new System.Drawing.Font("Microsoft YaHei UI",11)};form.Controls.Add(label);form.Shown+=async(s,e)=>{try{await Task.Run(()=>Install(args[0],message=>form.BeginInvoke(new Action(()=>label.Text=message))));}catch(Exception error){MessageBox.Show(form,"更新未完成，旧文件已尽可能恢复。\n"+error.Message+"\n\n创作资料保存在应用数据目录，不会被更新覆盖。","星匣更新",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{form.Close();}};Application.Run(form);}
 internal static void Install(string jobPath,Action<string> progress){string jobDir=Path.GetDirectoryName(Path.GetFullPath(jobPath));var job=UpdateProtocol.Serializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(jobPath));string target=Path.GetFullPath(UpdateProtocol.Text(job,"target")).TrimEnd(Path.DirectorySeparatorChar);if(target==Path.GetPathRoot(target).TrimEnd(Path.DirectorySeparatorChar)||!File.Exists(Path.Combine(target,"星匣.exe")))throw new Exception("安装目录无效");var p=UpdateProtocol.Verify(UpdateProtocol.Text(job,"manifest"),"windows");if(UpdateProtocol.VersionOf(UpdateProtocol.Text(p,"version"))<=UpdateProtocol.VersionOf(UpdateProtocol.Current))throw new Exception("已阻止旧版或相同版本安装");string package=UpdateProtocol.Text(job,"package");UpdateProtocol.VerifyFile(package,UpdateProtocol.Object(p,"windows"));
  int pid=Convert.ToInt32(job["pid"]);if(pid>0)try{using(var running=Process.GetProcessById(pid)){if(!running.WaitForExit(45000))throw new Exception("星匣仍在运行，请关闭后重试");}}catch(ArgumentException){}
  string stage=Path.Combine(jobDir,"stage-"+Guid.NewGuid().ToString("N")),backup=Path.Combine(jobDir,"backup-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);Directory.CreateDirectory(backup);var applied=new List<string>();bool success=false;string message="";
  try{progress("正在校验并展开更新包…");Extract(package,stage);string source=Path.Combine(stage,"Starcase-Update");if(!File.Exists(Path.Combine(source,"星匣.exe"))||!File.Exists(Path.Combine(source,"星匣.html"))||!File.Exists(Path.Combine(source,"service","server.py")))throw new Exception("更新包缺少必要文件");string versionFile=Path.Combine(source,"service","version.json");if(!File.Exists(versionFile)||UpdateProtocol.Text(UpdateProtocol.Serializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(versionFile)),"version")!=UpdateProtocol.Text(p,"version"))throw new Exception("更新包版本不匹配");progress("正在备份并替换应用…");foreach(string file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){string relative=file.Substring(source.Length+1),dest=Path.Combine(target,relative),old=Path.Combine(backup,relative);CheckParents(target,dest);Directory.CreateDirectory(Path.GetDirectoryName(dest));if(File.Exists(dest)){Directory.CreateDirectory(Path.GetDirectoryName(old));File.Copy(dest,old,true);}applied.Add(relative);File.Copy(file,dest,true);}success=true;message="已更新至 v"+UpdateProtocol.Text(p,"version")+"。创作资料记录已保留。";}catch(Exception error){var failures=new List<string>();foreach(string rel in applied.AsEnumerable().Reverse()){try{string dest=Path.Combine(target,rel),old=Path.Combine(backup,rel);if(File.Exists(old))File.Copy(old,dest,true);else if(File.Exists(dest))File.Delete(dest);}catch{failures.Add(rel);}}message="更新失败："+error.Message+(failures.Count>0?"；部分文件恢复失败，备份保留于 "+backup:"；已恢复原文件。");throw new Exception(message);}finally{File.WriteAllText(Path.Combine(jobDir,"install-result.json"),UpdateProtocol.Serializer().Serialize(new{success=success,message=message}));try{Process.Start(new ProcessStartInfo(Path.Combine(target,"星匣.exe")){UseShellExecute=true,WorkingDirectory=target});}catch{} }
 }
 internal static void RejectLink(string path){try{if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new Exception("安装路径包含链接，无法安全替换");}catch(FileNotFoundException){}catch(DirectoryNotFoundException){}}
 internal static void CheckParents(string root,string dest){RejectLink(dest);var current=new DirectoryInfo(Path.GetDirectoryName(dest));while(current!=null&&current.FullName.Length>=root.Length){RejectLink(current.FullName);if(string.Equals(current.FullName,root,StringComparison.OrdinalIgnoreCase))return;current=current.Parent;}throw new Exception("安装路径越界");}
 internal static void Extract(string package,string stage){long total=0;var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string root=Path.GetFullPath(stage)+Path.DirectorySeparatorChar;using(var archive=ZipFile.OpenRead(package)){if(archive.Entries.Count>5000)throw new Exception("更新包文件数量异常");foreach(var entry in archive.Entries){string name=entry.FullName.Replace('\\','/');if(!name.StartsWith("Starcase-Update/",StringComparison.Ordinal)||name.Contains(":")||name.Split('/').Any(x=>x==".."||x=="."||x.EndsWith(" ")||x.EndsWith("."))||((entry.ExternalAttributes>>16)&0xf000)==0xa000)throw new Exception("更新包包含不安全路径");string path=Path.GetFullPath(Path.Combine(stage,name));if(!path.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!seen.Add(path.TrimEnd(Path.DirectorySeparatorChar)))throw new Exception("更新包路径越界或重复");if(name.EndsWith("/")){Directory.CreateDirectory(path);continue;}total+=entry.Length;if(total>240L*1024*1024||entry.Length>80L*1024*1024)throw new Exception("更新包解压大小异常");Directory.CreateDirectory(Path.GetDirectoryName(path));entry.ExtractToFile(path,false);}}}
}
